from fastapi import FastAPI, Response, status
from fastapi.testclient import TestClient
import pytest

client = TestClient(FastAPI())

def test_none_return_annotation():
    app = FastAPI()

    @app.get("/none", status_code=status.HTTP_204_NO_CONTENT)
    def read_none() -> None:
        return None

    response = client.get("/none")
    assert response.status_code == 204
    assert response.text == ""

def test_no_return_annotation_none_value():
    app = FastAPI()

    @app.get("/no-annotation", status_code=status.HTTP_204_NO_CONTENT)
    def read_no_annotation():
        return None

    response = client.get("/no-annotation")
    assert response.status_code == 204
    assert response.text == ""

def test_string_none_return_annotation():
    app = FastAPI()

    @app.get("/string-none", status_code=status.HTTP_204_NO_CONTENT)
    def read_string_none() -> "None":
        return None

    response = client.get("/string-none")
    assert response.status_code == 204
    assert response.text == ""

def test_none_return_annotation_with_body_not_allowed():
    app = FastAPI()

    @app.get("/none-204", status_code=status.HTTP_204_NO_CONTENT)
    def read_none_204() -> None:
        return "this should be empty"

    response = client.get("/none-204")
    assert response.status_code == 204
    assert response.text == ""
